+        messageField.clear();
+        resettingAfterSend = false;
+        clearValidation();
+        sendButton.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean validateForm() {
+        clearValidation();
+        boolean valid = true;
+
+        if (nameField.getValue().isBlank()) {
+            setError(nameField, "Name is required");
+            valid = false;
+        }
+
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        if (!email.isBlank() && !isValidEmail(email)) {
+            setError(emailField, "Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isBlank() && phone.isBlank()) {
+            setError(emailField, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String message = messageField.getValue();
+        if (message.isBlank()) {
+            setError(messageField, "Message is required");
+            valid = false;
+        } else if (message.length() > 500) {
+            setError(messageField, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private boolean isValidEmail(String email) {
+        Validator<String> validator = emailField.getDefaultValidator();
+        return !validator.apply(email, new ValueContext(emailField)).isError();
+    }
+
+    private void setError(HasValidation field, String message) {
+        field.setErrorMessage(message);
+        field.setInvalid(true);
+    }
+
+    private void clearValidation() {
+        clearValidation(nameField);
+        clearValidation(emailField);
+        clearValidation(phoneField);
+        clearValidation(messageField);
+    }
+
+    private void clearValidation(HasValidation field) {
+        field.setInvalid(false);
+        field.setErrorMessage("");
+    }
+}
